##### Step 5: Integrate Applications with Secret Management

**Option A: Vault Agent Sidecar (Kubernetes)**

```yaml
# deployment.yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: claims-service
  namespace: production
spec:
  template:
    metadata:
      annotations:
        vault.hashicorp.com/agent-inject: "true"
        vault.hashicorp.com/role: "claims-service"
        vault.hashicorp.com/agent-inject-secret-db: "database/creds/claims-readonly"
        vault.hashicorp.com/agent-inject-template-db: |
          {{- with secret "database/creds/claims-readonly" -}}
          export DB_USERNAME="{{ .Data.username }}"
          export DB_PASSWORD="{{ .Data.password }}"
          {{- end }}
        vault.hashicorp.com/agent-inject-secret-api-keys: "secret/data/claims-service/api-keys"
        vault.hashicorp.com/agent-inject-template-api-keys: |
          {{- with secret "secret/data/claims-service/api-keys" -}}
          export SENDGRID_KEY="{{ .Data.data.sendgrid_api_key }}"
          export STRIPE_KEY="{{ .Data.data.stripe_api_key }}"
          {{- end }}
    spec:
      serviceAccountName: claims-service-sa
      containers:
      - name: claims-service
        image: gainwell/claims-service:1.2.3
        command:
        - /bin/sh
        - -c
        - source /vault/secrets/db && source /vault/secrets/api-keys && ./start.sh
```

**Option B: Application SDK Integration**

```csharp
// C# example using VaultSharp
using VaultSharp;
using VaultSharp.V1.AuthMethods.Kubernetes;

public class SecretManager
{
    private readonly IVaultClient _vaultClient;

    public SecretManager()
    {
        var vaultAddr = Environment.GetEnvironmentVariable("VAULT_ADDR");
        var k8sToken = File.ReadAllText("/var/run/secrets/kubernetes.io/serviceaccount/token");

        var authMethod = new KubernetesAuthMethodInfo("claims-service", k8sToken);
        var vaultSettings = new VaultClientSettings(vaultAddr, authMethod);

        _vaultClient = new VaultClient(vaultSettings);
    }

    public async Task<string> GetSecretAsync(string path, string key)
    {
        var secret = await _vaultClient.V1.Secrets.KeyValue.V2
            .ReadSecretAsync(path);

        return secret.Data.Data[key].ToString();
    }

    public async Task<DatabaseCredentials> GetDatabaseCredsAsync()
    {
        var creds = await _vaultClient.V1.Secrets.Database
            .GetCredentialsAsync("claims-readonly");

        return new DatabaseCredentials
        {
            Username = creds.Data.Username,
            Password = creds.Data.Password,
            LeaseId = creds.LeaseId,
            LeaseDuration = creds.LeaseDurationSeconds
        };
    }
}
```

```javascript
// Node.js example using node-vault
const vault = require('node-vault');

class SecretManager {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN // Obtained via K8s auth
    });
  }

  async getSecret(path) {
    const result = await this.client.read(path);
    return result.data.data;
  }

  async getDatabaseCreds(role) {
    const result = await this.client.read(`database/creds/${role}`);
    return {
      username: result.data.username,
      password: result.data.password,
      leaseId: result.lease_id,
      leaseDuration: result.lease_duration
    };
  }

  async renewLease(leaseId) {
    await this.client.write('sys/leases/renew', {
      lease_id: leaseId,
      increment: 3600 // Renew for 1 hour
    });
  }
}

module.exports = SecretManager;
```

**Option C: Azure Key Vault with Managed Identity**

```csharp
// C# with Azure Key Vault SDK
using Azure.Identity;
using Azure.Security.KeyVault.Secrets;

public class AzureSecretManager
{
    private readonly SecretClient _client;

    public AzureSecretManager(string keyVaultUrl)
    {
        // Uses DefaultAzureCredential (Managed Identity in Azure)
        _client = new SecretClient(
            new Uri(keyVaultUrl),
            new DefaultAzureCredential()
        );
    }

    public async Task<string> GetSecretAsync(string secretName)
    {
        KeyVaultSecret secret = await _client.GetSecretAsync(secretName);
        return secret.Value;
    }

    public async Task<Dictionary<string, string>> GetConnectionStringAsync()
    {
        var username = await GetSecretAsync("db-username");
        var password = await GetSecretAsync("db-password");
        var host = await GetSecretAsync("db-host");

        return new Dictionary<string, string>
        {
            ["ConnectionString"] = $"Server={host};Database=claims;User Id={username};Password={password};"
        };
    }
}
