##### Step 6: Implement Secret Rotation

**Automated Rotation Configuration**

```hcl
# Vault policy for rotation automation
path "database/rotate-root/claims-postgres" {
  capabilities = ["update"]
}

path "database/config/claims-postgres" {
  capabilities = ["read", "update"]
}
```

```bash
# Configure automatic rotation (every 90 days)
kubectl exec -n vault vault-0 -- vault write database/config/claims-postgres \
  plugin_name=postgresql-database-plugin \
  connection_url="postgresql://{{username}}:{{password}}@postgres-claims:5432/claims" \
  username="vault-admin" \
  password="$VAULT_ADMIN_PASSWORD" \
  allowed_roles="claims-readonly,claims-readwrite" \
  rotate_root_password=true

# Schedule rotation via CronJob
kubectl apply -f - <<EOF
apiVersion: batch/v1
kind: CronJob
metadata:
  name: vault-rotate-database-root
  namespace: vault
spec:
  schedule: "0 2 1 */3 *"  # Every 3 months at 2 AM on 1st
  jobTemplate:
    spec:
      template:
        spec:
          serviceAccountName: vault-rotation-sa
          containers:
          - name: rotate
            image: hashicorp/vault:1.15
            command:
            - /bin/sh
            - -c
            - vault write -force database/rotate-root/claims-postgres
            env:
            - name: VAULT_ADDR
              value: "http://vault:8200"
EOF
```

**Application-side Rotation Handling**

```csharp
public class DatabaseConnectionPool
{
    private IVaultClient _vault;
    private string _leaseId;
    private Timer _renewalTimer;

    public async Task InitializeAsync()
    {
        // Get initial credentials
        var creds = await _vault.V1.Secrets.Database
            .GetCredentialsAsync("claims-readonly");

        UpdateConnectionString(creds.Data.Username, creds.Data.Password);
        _leaseId = creds.LeaseId;

        // Schedule lease renewal (halfway through lease duration)
        var renewalInterval = TimeSpan.FromSeconds(creds.LeaseDurationSeconds / 2);
        _renewalTimer = new Timer(RenewLease, null, renewalInterval, renewalInterval);
    }

    private async void RenewLease(object state)
    {
        try
        {
            await _vault.V1.System.RenewLeaseAsync(_leaseId, increment: 3600);
        }
        catch (VaultApiException ex) when (ex.StatusCode == 400)
        {
            // Lease cannot be renewed, get new credentials
            await InitializeAsync();
        }
    }
}
```

