# Configure Kubernetes auth backend
resource "vault_auth_backend" "kubernetes" {
  type = "kubernetes"
}

resource "vault_kubernetes_auth_backend_config" "config" {
  backend            = vault_auth_backend.kubernetes.path
  kubernetes_host    = var.kubernetes_host
  kubernetes_ca_cert = var.kubernetes_ca_cert
}

# Create policy for claims service
resource "vault_policy" "claims_service" {
  name = "claims-service-policy"

  policy = <<EOT
path "secret/data/claims-service/*" {
  capabilities = ["read", "list"]
}

path "database/creds/claims-readonly" {
  capabilities = ["read"]
}

path "pki/issue/service-cert" {
  capabilities = ["create", "update"]
}
EOT
}

# Create Kubernetes auth role
resource "vault_kubernetes_auth_backend_role" "claims_service" {
  backend                          = vault_auth_backend.kubernetes.path
  role_name                        = "claims-service"
  bound_service_account_names      = ["claims-service-sa"]
  bound_service_account_namespaces = ["production"]
  token_ttl                        = 3600
  token_policies                   = [vault_policy.claims_service.name]
}

# Configure database secrets engine
resource "vault_database_secrets_mount" "postgres" {
  path = "database"

  postgresql {
    name              = "claims-postgres"
    connection_url    = "postgresql://{{username}}:{{password}}@${var.postgres_host}:5432/claims"
    username          = var.vault_db_admin_user
    password          = var.vault_db_admin_password
    allowed_roles     = ["claims-readonly", "claims-readwrite"]
  }
}

resource "vault_database_secret_backend_role" "readonly" {
  backend             = vault_database_secrets_mount.postgres.path
  name                = "claims-readonly"
  db_name             = vault_database_secrets_mount.postgres.postgresql[0].name
  creation_statements = [
    "CREATE USER '{{name}}' WITH PASSWORD '{{password}}' VALID UNTIL '{{expiration}}';",
    "GRANT SELECT ON ALL TABLES IN SCHEMA public TO '{{name}}';"
  ]
  default_ttl         = 86400  # 24 hours
  max_ttl             = 259200 # 72 hours
}
